"use client";

// One of Krystal's voice memos: a play/pause button with the transcript beneath it.
// Audio is pre-generated by agents/generate-audio.ts into public/audio.
// All of Krystal's text uses the pixel font, so her voice looks the same everywhere.

import { useEffect, useRef, useState } from "react";

/** Play/pause for one memo. Used on its own by the floor briefing. */
export function MemoPlayButton({
  title,
  audio,
  onTime,
  onPlayingChange,
}: {
  title: string;
  audio: string;
  /** Fires while the clip plays so a multi-page transcript can follow along. */
  onTime?: (current: number, duration: number) => void;
  onPlayingChange?: (playing: boolean) => void;
}) {
  const ref = useRef<HTMLAudioElement | null>(null);
  const onTimeRef = useRef(onTime);
  const onPlayingRef = useRef(onPlayingChange);
  const [playing, setPlaying] = useState(false);

  useEffect(() => {
    onTimeRef.current = onTime;
    onPlayingRef.current = onPlayingChange;
  });

  useEffect(() => () => ref.current?.pause(), []);

  const setPlay = (next: boolean) => {
    setPlaying(next);
    onPlayingRef.current?.(next);
  };

  const toggle = () => {
    if (!ref.current) {
      const el = new Audio(`/audio/${audio}`);
      el.ontimeupdate = () => {
        if (!ref.current) return;
        onTimeRef.current?.(ref.current.currentTime, ref.current.duration || 0);
      };
      el.onended = () => setPlay(false);
      ref.current = el;
    }
    if (playing) {
      ref.current.pause();
      setPlay(false);
    } else {
      // Fresh press from the start: tell the parent so it can reset the page.
      if (ref.current.currentTime < 0.05) onTimeRef.current?.(0, ref.current.duration || 0);
      ref.current.play().then(() => setPlay(true)).catch(() => setPlay(false));
    }
  };

  return (
    <button type="button" onClick={toggle} className="pixel-button shrink-0 whitespace-nowrap" aria-label={playing ? `Pause ${title}` : `Play ${title}`}>
      {playing ? "❚❚ Pause" : "▶ Play"}
    </button>
  );
}

export function KrystalMemo({ title, audio, text }: { title: string; audio: string; text: string }) {
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-3">
        <MemoPlayButton title={title} audio={audio} />
        <p className="font-pixel text-[10px] text-[var(--cc-accent)]">{title}</p>
      </div>
      <p className="font-pixel text-[11px] leading-loose text-[var(--cc-ink)]">&ldquo;{text}&rdquo;</p>
    </div>
  );
}
